const assert = require('assert');
const fs = require('fs');
const cp = require('child_process');
function lines(text) { return text.trim().split(/\r?\n/).filter(Boolean); }
function hasId(line, id) { return new RegExp(`(^|\\D)${id}(\\D|$)`).test(line); }
function assertTodoLine(line, id, task, done) {
  assert(line.includes(task), `missing task ${task}: ${line}`);
  assert(hasId(line, id), `missing id ${id}: ${line}`);
  const doneMarker = /\[x\]|\[done\]|✓|✔|✅/i.test(line);
  const openMarker = /\[\s\]|☐|○/i.test(line);
  assert.strictEqual(doneMarker, done, `done marker mismatch: ${line}`);
  if (!done) assert(openMarker, `missing open marker: ${line}`);
}
try { fs.unlinkSync('todo.json'); } catch {}
cp.execFileSync(process.execPath, ['todo.js', 'add', '写文档']);
cp.execFileSync(process.execPath, ['todo.js', 'add', '修bug']);
let list = lines(cp.execFileSync(process.execPath, ['todo.js', 'list'], {encoding:'utf8'}));
assert.strictEqual(list.length, 2);
assertTodoLine(list[0], 1, '写文档', false);
assertTodoLine(list[1], 2, '修bug', false);
cp.execFileSync(process.execPath, ['todo.js', 'done', '1']);
list = lines(cp.execFileSync(process.execPath, ['todo.js', 'list'], {encoding:'utf8'}));
assert.strictEqual(list.length, 2);
assertTodoLine(list[0], 1, '写文档', true);
assertTodoLine(list[1], 2, '修bug', false);
console.log('ALL TESTS PASS');

const assert = require('assert');
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const TODO_JS = path.join(__dirname, 'todo.js');
const TODO_JSON = path.join(__dirname, 'todo.json');

try { fs.unlinkSync(TODO_JSON); } catch (e) {}

function run(cmd) {
  return execSync(`node "${TODO_JS}" ${cmd}`, { encoding: 'utf8' }).trim();
}

run('add "Buy milk"');
run('add "Walk dog"');

let output = run('list');
let lines = output.split('\n');
assert.strictEqual(lines.length, 2);
assert.match(lines[0], /^1\.\s+\[ \]\s+Buy milk$/);
assert.match(lines[1], /^2\.\s+\[ \]\s+Walk dog$/);

run('done 1');

output = run('list');
lines = output.split('\n');
assert.match(lines[0], /^1\.\s+\[x\]\s+Buy milk$/);
assert.match(lines[1], /^2\.\s+\[ \]\s+Walk dog$/);

const raw = fs.readFileSync(TODO_JSON, 'utf8');
const data = JSON.parse(raw);
assert(Array.isArray(data));
assert.strictEqual(data.length, 2);
assert.strictEqual(data[0].text, 'Buy milk');
assert.strictEqual(data[0].done, true);
assert.strictEqual(data[1].text, 'Walk dog');
assert.strictEqual(data[1].done, false);

const todoJsContent = fs.readFileSync(TODO_JS, 'utf8');
assert(todoJsContent.includes('add'));
assert(todoJsContent.includes('list'));
assert(todoJsContent.includes('done'));

console.log('ALL TESTS PASS');

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const DATA_FILE = path.join(__dirname, 'todo.json');

function readTodos() {
  try {
    const data = fs.readFileSync(DATA_FILE, 'utf8');
    return JSON.parse(data);
  } catch (e) {
    return [];
  }
}

function writeTodos(todos) {
  fs.writeFileSync(DATA_FILE, JSON.stringify(todos, null, 2));
}

const [, , cmd, ...args] = process.argv;
const todos = readTodos();

switch (cmd) {
  case 'add': {
    const text = args.join(' ');
    if (!text) {
      console.error('Usage: todo add <task>');
      process.exit(1);
    }
    todos.push({ text, done: false });
    writeTodos(todos);
    break;
  }
  case 'list': {
    todos.forEach((todo, i) => {
      const marker = todo.done ? '[x]' : '[ ]';
      console.log(`${i + 1}. ${marker} ${todo.text}`);
    });
    break;
  }
  case 'done': {
    const index = parseInt(args[0], 10);
    if (isNaN(index) || index < 1 || index > todos.length) {
      console.error('Usage: todo done <index>');
      process.exit(1);
    }
    todos[index - 1].done = true;
    writeTodos(todos);
    break;
  }
  default:
    console.error('Usage: todo <add|list|done> [args]');
    process.exit(1);
}
